// Purpose: ROW-144 (REQ-009) — through the check endpoint, affix-expanded inflected forms and capital-only
// dictionary entries written title-case mid-sentence without their accents (Tecnicos, Bogota, a generated
// sample) are flagged, each with its accented form as the first suggestion.
// Provenance: the row's named examples; inflected forms generated by the dictionary oracle (plurals and
// feminines of accentPopulation's words that the oracle holds); capital-only entries from a hand-typed
// list of place and person names, kept only where the oracle holds the capitalised accented form and not
// its lower case; every candidate filtered so its unaccented form has exactly one accent restoration in
// the dictionary; no expected value comes from the product.
//
// Test argument
// ROW-144 promise: affix-expanded inflected forms and capital-only dictionary entries, written
//   title-case mid-sentence without their accents (Tecnicos, Bogota), are flagged with the accented form
//   first (REQ-009 "unless the same word with its accents restored is in the dictionary, in which case
//   it is flagged"; A-036; the accented form first, as REQ-010 puts the expected correction of an
//   accent error first).
// ROW-144 wrong product: one that restores accents by looking the word up in the dictionary's stem list
//   only, so "Tecnicos" (técnico + plural affix) and "Bogota" are taken as names and pass; one that
//   lower-cases before restoring, so a capital-only entry ("Perú", never "perú") is never found; or one
//   that flags them but puts another suggestion first.
// ROW-144 given: Tecnicos and Bogota, ~30 generated title-cased unaccented inflected forms and ~20
//   unaccented capital-only entries, mid-sentence; decoys in the same text: their correct accented
//   forms mid-sentence (unflagged); when: POST /api/check; then: exactly the unaccented forms are
//   flagged at their offsets, and each one's first suggestion is its accented form (for an inflected
//   form, title or lower case; for a capital-only entry, exactly as the entry is written).
// ROW-144 controls: the same inflected forms unaccented in lower case are flagged — they are
//   misspellings to the product whatever the capital rule says.
// ROW-144 technique: a generated sample over the dictionary's affix-expanded forms and capital-only
//   entries (fresh each run), plus the row's examples; exact comparison, then the first suggestion of
//   every matched flag.
// cases: ROW-144 target=ROW-144-unaccented-title-case-inflections-and-capital-only-entries-flagged-with-the-accented-form-first control=ROW-144-control-the-unaccented-inflections-in-lower-case-flagged

import { expect, test } from '@playwright/test';
import { accentPopulation, asActor, freshRandom, hasInclusiveReading, isDictionaryWord, type Rng } from './harness';
import { Offer, accentRestorations, expectExact, fillers, stripAcute, titleCase } from './names-terms-helpers';

// Capital-only entries' candidates: places and names written with an accent (kept only if the oracle agrees).
const CAPITAL_CANDIDATES = [
  'Perú', 'Panamá', 'México', 'Japón', 'Canadá', 'París', 'Málaga', 'Cádiz', 'Córdoba', 'Mérida', 'Asunción',
  'Bélgica', 'Túnez', 'Turquía', 'África', 'Aragón', 'Castellón', 'Almería', 'Jaén', 'Cáceres', 'Ávila', 'Gijón',
  'Logroño', 'José', 'María', 'Martín', 'Óscar', 'Ramón', 'Andrés', 'Jesús', 'Iván', 'Moisés', 'Mónica', 'Lucía',
  'Raúl', 'Víctor', 'Héctor', 'Inés', 'Álvaro', 'Joaquín', 'Sebastián', 'Germán', 'Ángela', 'Bárbara', 'Cristóbal',
  'Nicolás', 'Adrián', 'Rubén', 'Jiménez', 'Sánchez', 'Gómez', 'González', 'Rodríguez', 'Hernández', 'Fernández',
  'López', 'Álvarez', 'Gutiérrez', 'Ramírez', 'Vázquez', 'Domínguez', 'Suárez', 'Núñez', 'Ibáñez', 'Benítez', 'Méndez',
];

type Target = { bad: string; good: string; kind: 'inflected' | 'capital-only' | 'named' };

/** The unaccented form is no word in any casing and has exactly one accent restoration: `good`. */
function clean(bad: string, good: string): boolean {
  const lower = bad.toLowerCase();
  if (isDictionaryWord(bad) || isDictionaryWord(lower) || hasInclusiveReading(lower)) return false;
  const r = accentRestorations(bad);
  return r.length === 1 && r[0] === good;
}

/** Plurals and feminines of the dictionary's accented words that the oracle holds, title-cased and stripped. */
function inflected(rng: Rng, n: number): Target[] {
  const out: Target[] = [];
  for (const p of rng.shuffle(accentPopulation())) {
    const w = p.word;
    const forms = w.endsWith('o') ? [w + 's', w.slice(0, -1) + 'a', w.slice(0, -1) + 'as'] : /[aeiu]$/.test(w) ? [w + 's'] : [];
    for (const f of forms) {
      if (!/[áéíóú]/.test(f) || !isDictionaryWord(f)) continue;
      const good = titleCase(f);
      const bad = stripAcute(good);
      if (isDictionaryWord(good) && clean(bad, good)) out.push({ bad, good, kind: 'inflected' });
      break;
    }
    if (out.length >= n) break;
  }
  return out;
}

function capitalOnly(rng: Rng, n: number): Target[] {
  return rng
    .shuffle(CAPITAL_CANDIDATES)
    .filter((good) => isDictionaryWord(good) && !isDictionaryWord(good.toLowerCase()) && clean(stripAcute(good), good))
    .slice(0, n)
    .map((good) => ({ bad: stripAcute(good), good, kind: 'capital-only' as const }));
}

test('ROW-144-unaccented-title-case-inflections-and-capital-only-entries-flagged-with-the-accented-form-first', async () => {
  asActor('anonymous');
  const rng = freshRandom();
  const infl = inflected(rng, 30);
  const caps = capitalOnly(rng, 20);
  if (infl.length < 20 || caps.length < 10) throw new Error(`setup: the generated sample is too small (${infl.length} inflected, ${caps.length} capital-only)`);
  const targets: Target[] = [{ bad: 'Tecnicos', good: 'Técnicos', kind: 'named' }, { bad: 'Bogota', good: 'Bogotá', kind: 'named' }, ...infl, ...caps];

  const o = new Offer().put(fillers(rng, 2, { capital: true }));
  for (const t of rng.shuffle(targets)) {
    o.put(' ' + fillers(rng, 1 + rng.int(2)) + ' ').flag(t.bad, `${t.kind} ${t.bad}`);
    o.put(' ' + fillers(rng, 1) + ' ').keep(t.good, `correct ${t.good}`);
  }
  o.put(' ' + fillers(rng, 2) + '.');
  const c = await expectExact(o, `ROW-144: unaccented title-case inflected forms and capital-only entries mid-sentence are flagged (seed ${rng.seed})`);

  const byBad = new Map(targets.map((t) => [t.bad, t]));
  const wrongFirst = c.matched
    .map(({ flag }) => {
      const t = byBad.get(flag.word) as Target;
      const first = flag.suggestions[0];
      const ok = t.kind === 'inflected' || t.bad === 'Tecnicos' ? first === t.good || first === t.good.toLowerCase() : first === t.good;
      return ok ? null : `${t.bad}: first suggestion ${JSON.stringify(first ?? null)}, expected ${t.good}`;
    })
    .filter((x): x is string => x !== null);
  expect(wrongFirst, `ROW-144: each unaccented form's first suggestion is its accented form (seed ${rng.seed})`).toEqual([]);
  expect(c.matched.length, 'ROW-144: every target was matched before its suggestion was read').toBe(targets.length);
});

test('ROW-144-control-the-unaccented-inflections-in-lower-case-flagged', async () => {
  asActor('anonymous');
  const rng = freshRandom();
  const o = new Offer().put(fillers(rng, 2, { capital: true })).put(' ').flag('tecnicos', 'tecnicos lower case');
  for (const t of inflected(rng, 5)) o.put(' ' + fillers(rng, 1) + ' ').flag(t.bad.toLowerCase(), 'unaccented inflected form in lower case');
  o.put(' ' + fillers(rng, 2) + '.');
  await expectExact(o, `ROW-144 control: the unaccented inflected forms in lower case are flagged (seed ${rng.seed})`);
});
